/** branch is explicit HOST observation; do not read product's computed remaining. */
export function remainingInput(x: Host, branch: "empty" | "A" | "AB" | "releasedA" | "BOnA", active: ResourceAllocationV1[], revision: number,
  previousRef: ResourceRemainingV1["previousRef"]): ResourceRemainingV1 {
  const view = x.store.read("author"), a = branch === "A" || branch === "AB", b = branch === "AB", onA = branch === "BOnA";
  const values = branch === "AB" ? { slots: 0, budget: 0, count: 0 } : a || onA ? { slots: 1, budget: 3, count: 1 } : { slots: 2, budget: 6, count: 2 };
  const sorted = [...active].sort((a, b) => a.allocationId < b.allocationId ? -1 : 1);
  const occupied = (workerId: string, id: string | null) => ({ workerId, slots: id ? 2 : 3, cpu: id ? 4 : 6,
    gpu: id ? 1 : 2, budget: id ? 5 : 8, available: true, occupiedBy: id });
  return { version: "l8-s2-resource-remaining-fixture-v1", recordId: `remaining:${branch}:${revision}`, revision,
    poolScope: { ...PHYSICAL_POOL74 }, acquisitionRef: x.acquisitionRef, previousRef,
    poolRevision: x.store.resourceInventory(PHYSICAL_POOL74.poolId).poolRevision,
    workCuts: [{ missionId: view.missionId, generationId: view.generationId, headRevision: view.revision,
      inventoryRevision: view.inventoryRevision, observedEventSequence: x.events.cursor("author").sequence }],
    includedAllocationIds: sorted.map(a => a.allocationId), includedAllocationsDigest: digest(sorted),
    workers: [occupied("worker-a", a ? "allocation:A" : onA ? "allocation:B" : null), occupied("worker-b", b ? "allocation:B" : null)],
    accounts: [{ accountId: "shared", slots: values.slots, budget: values.budget }], maxConcurrentRemaining: values.count };
}
export function resourceWitness(x: Host, lease: FamilyLeaseV3, role: "A" | "B" | "R" = "A", workerId?: string) {
  const assignment = assignmentInput(x, lease, role, workerId);
  const assignmentRef = x.authority.registerResourceSource(document(assignment.version, assignment));
  let remainingRef = x.authority.resourceCurrent(PHYSICAL_POOL74.poolId)?.remainingRef;
  if (!remainingRef) {
    const remaining = remainingInput(x, "empty", [], 1, null);
    remainingRef = x.authority.registerResourceSource(document(remaining.version, remaining));
  }
  return x.authority.resolveResourceWitness({ acquisitionRef: x.acquisitionRef, assignmentRef, remainingRef });
}
export function publishRemaining(x: Host, remaining: ResourceRemainingV1) {
  return x.authority.registerResourceSource(document(remaining.version, remaining));
}
